import cv2, numpy as np
from PIL import Image
im=cv2.imread('first_frame.png'); b,g,r=cv2.split(im)
# report connected comps for possible orange metrics
metrics={
'orange1':(r>150)&(r>g*1.25)&(g>b*1.15),
'orange2':(r>130)&((r.astype(int)-g)>25)&((g.astype(int)-b)>10),
'skinorange':(r>140)&(g>60)&(g<180)&(b<130)&(r>g*1.2),
'brightgray':(r>150)&(g>150)&(b>150)&(np.max(im,2)-np.min(im,2)<35),
'dark':np.max(im,2)<55,
}
for name,m in metrics.items():
 n,lab,stats,cents=cv2.connectedComponentsWithStats(m.astype(np.uint8),8)
 comps=sorted([(int(s[4]),tuple(map(int,s[:4])),tuple(np.round(c,1))) for s,c in zip(stats[1:],cents[1:])],reverse=True)[:15]
 print('\\n',name,'pixels',m.sum())
 print(*comps,sep='\\n')
# HSV hist peak bins spatial centroid
hsv=cv2.cvtColor(im,cv2.COLOR_BGR2HSV)
for lo,hi in [(0,10),(10,20),(20,30),(30,45),(45,75),(75,100),(100,130),(130,160),(160,180)]:
 m=(hsv[:,:,0]>=lo)&(hsv[:,:,0]<hi)&(hsv[:,:,1]>80)
 y,x=np.where(m)
 print('h',lo,hi,'n',len(x),'cent', (round(x.mean(),1),round(y.mean(),1)) if len(x) else None,'bbox', (x.min(),y.min(),x.max(),y.max()) if len(x) else None)
PY"

