import cv2,numpy as np
im=cv2.imread('first_frame.png'); G=cv2.cvtColor(im,cv2.COLOR_BGR2GRAY); ed=cv2.Canny(G,30,90)
lines=cv2.HoughLinesP(ed,1,np.pi/720,threshold=45,minLineLength=55,maxLineGap=12)
out=[]
for l in lines[:,0]:
 x1,y1,x2,y2=map(int,l); L=np.hypot(x2-x1,y2-y1); ang=np.degrees(np.arctan2(y2-y1,x2-x1))
 if (y1+y2)/2<520:out.append((L,ang,(x1,y1,x2,y2)))
for z in sorted(out,reverse=True)[:150]: print(f'{z[0]:6.1f} {z[1]:6.1f}',z[2])
